import axios from "axios";
import MaterialTable, { MTableToolbar } from "material-table";
import { Spinner } from "reactstrap";
import React, { Component } from "react";
import { Modal, ModalHeader, ModalBody } from "reactstrap";
import { connect } from "react-redux";
import PropTypes from "prop-types";
import { login, loadUser } from "../../../actions/authActions";
import { clearErrors } from "../../../actions/errorActions";
import store from "../../../store";
import {
  Button,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Toolbar
} from "@material-ui/core";

class UserAccessModal extends Component {
  state = {
    modal: false,
    chooseUserRowData: [],
    selectedUserRowData: [],
    tableLoaded: false,
    columns: [
      { title: "ID", field: "id" },
      { title: "Name", field: "name" }
    ]
  };
  componentDidMount() {
    this.retrieveFromDb();
  }
  toggle = () => {
    this.setState({
      modal: !this.state.modal
    });
  };
  retrieveFromDb = () => {
    this.setState(state => ({
      tableLoaded: false,
      chooseUserRowData: state.chooseUserRowData
    }));
    axios
      .get("/api/userList")
      .then(res => {
        var chooseUserRowData = res.data.map((x, index) => {
          return {
            id: x._id,
            name: x.name
          };
        });

        this.setState(state => ({
          tableLoaded: true,
          chooseUserRowData
        }));
      })
      .catch(err => console.log(err));
  };

  addUser = event => {
    const chooseUserRowData = this.state.chooseUserRowData;
    const selectedUserRowData = this.state.selectedUserRowData;
    /*var selectedUserRowData = this.state.selectedUserRowData;
    var removedUser = chooseUserRowData.splice(event.tableData.id, 1);
    chooseUserRowData1.splice(event.tableData.id, 1);
    const addObject = {
      id: chooseUserRowData1[event.tableData.id].id,
      name: chooseUserRowData1[event.tableData.id].name
    };*/
    chooseUserRowData = chooseUserRowData.filter((x, index) => {
      if (event.id == x.id) {
        selectedUserRowData.push(x);
      }
      return x.id != event.id;
    });
    //selectedUserRowData.push(chooseUserRowData.pop());
    console.log(event);

    //selectedUserRowData.push(removedUser);

    this.setState({
      selectedUserRowData,
      chooseUserRowData
    });
    //console.log(event.id);
  };

  rows = [
    { namee: "foryo", calo7ries: 159 },
    { namee: "fosdfryo", calo7ries: 1759 },
    { namee: "forhgfyo", calo7ries: 15769 }
    /*this.createData("Frozen yoghurt", 159),
    this.createData("Ice cream sandwich", 237),
    this.createData("Eclair", 262),
    this.createData("Cupcake", 305),
    this.createData("Gingerbread", 356)*/
  ];

  render() {
    return (
      <div>
        <Button
          className="mt-2 mb-3"
          variant="contained"
          color="primary"
          onClick={this.toggle}
        >
          Assign Users
        </Button>
        <Modal size={"lg"} isOpen={this.state.modal} toggle={this.toggle}>
          <ModalHeader toggle={this.toggle}>Assign Users</ModalHeader>
          <ModalBody>
            {this.state.tableLoaded ? (
              <div>
                <h5>Choose Users</h5>
                <TableContainer component={Paper}>
                  <Table aria-label="simple table">
                    <TableHead>
                      <TableRow>
                        <TableCell>User IDs</TableCell>
                        <TableCell>Name</TableCell>
                      </TableRow>
                    </TableHead>
                    <TableBody>
                      {this.state.chooseUserRowData.map(row => (
                        <TableRow
                          key={row.id}
                          onClick={this.addUser.bind(this, row)}
                        >
                          <TableCell component="th" scope="row">
                            {row.id}
                          </TableCell>
                          <TableCell>{row.name}</TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </TableContainer>
                <div className="mb-2"> </div>
                <h5>Selected Users</h5>
                <TableContainer component={Paper}>
                  <Table aria-label="simple table">
                    <TableHead>
                      <TableRow>
                        <TableCell>User IDs</TableCell>
                        <TableCell>Name</TableCell>
                      </TableRow>
                    </TableHead>
                    <TableBody>
                      {this.state.selectedUserRowData.map(row => (
                        <TableRow
                          key={row.id}
                          //onClick={this.addUser.bind(this, row)}
                        >
                          <TableCell component="th" scope="row">
                            {row.id}
                          </TableCell>
                          <TableCell>{row.name}</TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </TableContainer>
              </div>
            ) : (
              <div
                style={{
                  display: "flex",
                  justifyContent: "center"
                }}
              >
                <Spinner animation="border" />
              </div>
            )}
          </ModalBody>
        </Modal>
      </div>
    );
  }
}

const mapStateToProps = state => ({
  isAutheticated: state.auth.isAutheticated,
  error: state.error
});

export default connect(mapStateToProps, null)(UserAccessModal);
//mapStateToProps gets state variables from elsewhere in the app.
//the stuff in the curly braces are methods brought in to modify state in other parts of the app
//all these things will be declared in the component props
